<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $reference
 * @property string $payment_id
 * @property string|null $order_id
 * @property int $amount
 * @property string $currency
 * @property string $status
 * @property string|null $reason
 * @property string|null $note
 * @property string|null $gateway_refund_id
 * @property string|null $failure_reason
 * @property string|null $requested_by
 * @property string|null $approved_by
 * @property Carbon|null $processed_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Refund extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'rfd';

    protected $fillable = [
        'reference', 'payment_id', 'order_id', 'amount', 'currency', 'status', 'reason', 'note', 'gateway_refund_id',
        'failure_reason', 'requested_by', 'approved_by', 'processed_at',
    ];

    protected function casts(): array
    {
        return [
            'processed_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Payment, $this> */
    public function payment(): BelongsTo
    {
        return $this->belongsTo(Payment::class);
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }
}
